export async function mountMaintenance(node,{api,esc,toast}){
 const render=async()=>{if(!node.isConnected)return;try{const s=await api('/api/maintenance/status');const busy=['running','verifying'].includes(s.status);node.innerHTML=`<div class="section-head"><div><h3>自用备份与恢复</h3><small>${esc(s.stage||'保留源码、记录、行情与运行依赖')}${s.error?' · '+esc(s.error):''}</small></div><button id="makeSystemBackup" class="secondary" ${busy?'disabled':''}>${busy?'备份校验中…':'创建完整恢复点'}</button></div><p class="muted">${esc(s.notice)}</p><details><summary>恢复点 ${s.backups.length} 个</summary>${s.backups.slice(0,6).map(b=>`<p><b>${esc(b.createdAt)} · ${b.status==='complete'?'完整':'未完成'}</b><br><code>${esc(b.path)}</code><br>${b.files} 文件 · ${(b.bytes/1024**3).toFixed(2)} GB · ${b.verifiedAt?'已校验 '+esc(b.verifiedAt):'校验记录待核'}</p>`).join('')}</details><p>恢复方法：项目 docs/定格版_日常维护与恢复.md。先在隔离目录验证，再停APP切换；不要覆盖后续新增记录。</p>`;node.querySelector('#makeSystemBackup').onclick=async()=>{try{await api('/api/maintenance/backup',{method:'POST',body:'{}'});toast('备份已开始，原记录继续保留');await render()}catch(e){toast(e.message,true)}};if(busy)setTimeout(render,3000)}catch(e){node.textContent='备份状态读取失败：'+e.message}};await render();
}
